set -eu
probe_user="galera_probe_${NODE_NAME}"
probe_password=[REDACTED]
probe_file="/root/.galera-probe-${NODE_NAME}.cnf"
sudo -n mariadb --protocol=socket --batch <<GALERA_SQL
CREATE OR REPLACE USER '${probe_user}'@'10.100.30.%' IDENTIFIED BY [REDACTED];
GRANT SELECT, INSERT ON galera_benchmark.* TO '${probe_user}'@'10.100.30.%';
GALERA_SQL
printf '[client]\nuser=%s\npassword=[REDACTED] "$probe_user" "$probe_password" | sudo -n tee "$probe_file" >/dev/null
sudo -n chmod 0600 "$probe_file"
sudo -n mariadb --defaults-extra-file="$probe_file" --protocol=TCP --host="$NODE_IP" --connect-timeout=5 --batch --skip-column-names <<'GALERA_SQL'
SET SESSION wsrep_sync_wait=1;
SELECT CONCAT('tcp_reader=',@@hostname), id, origin, marker FROM galera_benchmark.replication_proof WHERE id=401;
INSERT INTO galera_benchmark.replication_proof (id, origin, marker) VALUES (402, 'node2', 'tcp-write-through-node2-ip');
SELECT CONCAT('tcp_writer=',@@hostname), CONCAT('endpoint_ip=',@@bind_address), id, origin, marker, CURRENT_USER() FROM galera_benchmark.replication_proof WHERE id IN (401,402) ORDER BY id;
GALERA_SQL
printf 'TCP_PROBE node=%s target=%s result=success\n' "$NODE_NAME" "$NODE_IP"

