sudo -n mariadb --defaults-extra-file="$probe_file" --protocol=TCP --host="$NODE_IP" --connect-timeout=5 --batch --skip-column-names <<'GALERA_SQL'
SET SESSION wsrep_sync_wait=1;
SELECT CONCAT('tcp_final_reader=',@@hostname), id, origin, marker FROM galera_benchmark.replication_proof WHERE id IN (401,402,403) ORDER BY id;
SELECT CONCAT('all_rows=',COUNT(*)), CONCAT('all_id_sum=',SUM(id)) FROM galera_benchmark.replication_proof;
SHOW GLOBAL STATUS WHERE Variable_name IN ('wsrep_cluster_size','wsrep_cluster_status','wsrep_connected','wsrep_ready','wsrep_local_state_comment');
GALERA_SQL
printf 'TCP_FINAL node=%s target=%s service=%s\n' "$NODE_NAME" "$NODE_IP" "$(systemctl is-active mariadb)"

