set -eu
printf 'FINAL node=%s ip=%s service=%s enabled=%s\n' "$NODE_NAME" "$NODE_IP" "$(systemctl is-active mariadb)" "$(systemctl is-enabled mariadb)"
sudo -n mariadb --protocol=socket --batch --skip-column-names <<'GALERA_SQL'
SELECT CONCAT('server=',@@hostname), CONCAT('node_name=',@@wsrep_node_name), CONCAT('node_address=',@@wsrep_node_address), CONCAT('cluster=',@@wsrep_cluster_name);
SHOW GLOBAL VARIABLES WHERE Variable_name IN ('wsrep_cluster_address','wsrep_sst_method','wsrep_provider_options','bind_address','binlog_format','default_storage_engine','innodb_autoinc_lock_mode');
SHOW GLOBAL STATUS WHERE Variable_name IN ('wsrep_cluster_size','wsrep_cluster_status','wsrep_connected','wsrep_ready','wsrep_local_state','wsrep_local_state_comment','wsrep_incoming_addresses','wsrep_cluster_state_uuid','wsrep_last_committed');
SELECT CONCAT('proof_rows=',COUNT(*)), CONCAT('proof_id_sum=',SUM(id)), CONCAT('proof_max_id=',MAX(id)) FROM galera_benchmark.replication_proof;
SELECT CONCAT('temporary_probe_users=',COUNT(*)) FROM mysql.global_priv WHERE User LIKE 'galera_probe_%';
GALERA_SQL
ss -lntp | sed -n '/:3306\|:4567\|:4568\|:4444/p'

